		{
			code: 'a { color: hsl(FROM lch(0 0 10) 0 s l) }',
			fixed: 'a { color: hsl(FROM lch(0 0 10deg) 0deg s l) }',
			warnings: [
				{
					message: messages.expected('0', '0deg'),
					column: 33,
					endLine: 1,
					endColumn: 34,
					fix: {
						range: [32, 33],
						text: '0deg',
					},
				},
				{
					message: messages.expected('10', '10deg'),
